const PICKUP=['Are you a squeaky toy? Because I can’t stop thinking about you.','Is your name Wi-Fi? Because I’m feeling a connection, but only near the router.','Do you have a map? I keep getting lost in your eyes and also in this city.','Are you a tennis ball? Because I would chase you into traffic.','My owner said I’m a good boy. Want a second opinion?','Is it hot in here, or is it just my fur?','Are you a belly rub? Because you make my leg kick.'];

function scratch(c){c.drop('ticket');const r=c.rnd();c.award('scratch');if(r<.5){c.say('You scratch: BONE, BONE, CAT. So close. The cat on the ticket is smirking.');}else if(r<.85){c.earn(10);c.say('BONE, BONE, BONE! You win $10. You consider retiring.');}else{c.earn(25);c.say('Three golden bones! $25! You howl. Pixel doesn’t look up.');}}
// Slots at Lucky Paws: $5 a spin, seeded.
function slots(c){if(!c.pay(5))return;c.time(5);c.award('slots');const r=c.rnd();if(r<.55){c.say('CHERRY · BONE · LEMON. Bertha eats your $5 and plays a sad trombone. Rude.');}else if(r<.85){c.earn(12);c.say('BONE · BONE · BONE! $12 rattles out. Big Bertha winks a bulb at you.');}else if(r<.98){c.earn(30);c.say('Three DAWG coins! $30! Lights flash. A retiree claps politely.');}else{c.earn(100);c.say('JACKPOT! Sirens! Confetti! $100! Security checks your paws for magnets!');}}

