// Nova comes up after you return her notebook, once the show is on (2 AM).
function wish(c){c.flag('wished',true);c.say('You toss a coin and wish for a good night. The fountain gurgles. You choose to interpret that as a yes.');c.award('fountain');}
function novaHere(c){return c.flag('novaDate')&&c.state.minute>=240;}
function buy(c,item,price,text){if(c.has(item)){c.say('You already have one. Restraint: you’re learning.');return;}if(!c.pay(price))return;c.give(item,true);c.say(text+` (−$${price})`);}

export const DIALOGS={
 mugsy:{ask:c=>({who:'Mugsy',prompt:'"What’ll it be, sport?"',options:[{id:'whiskey',label:'A Whiskey Biscuit. ($8)'},{id:'rocket',label:'Rocket Fuel. ($6) Make it a double.'},{id:'water',label:'Tap water. (free)'},{id:'tips',label:'Any advice for tonight?'},{id:'bye',label:'Nothing, thanks.'}]}),
  answer:(c,o)=>{if(o==='whiskey'){if(c.has('whiskey')){c.say('"Drink the one you got first," Mugsy grunts.','Mugsy');return;}if(c.pay(8)){c.give('whiskey',true);c.say('Mugsy slides a Whiskey Biscuit down the bar. It stops exactly in front of you. He has done this a thousand times. (−$8)','Mugsy');}}
   else if(o==='rocket'){if(c.flag('rocket')){c.die('rocket');return;}if(c.pay(6)){c.flag('rocket',true);c.say('You drink the Rocket Fuel. Your fur stands up. You see through time. "One’s your limit, kid," Mugsy warns. "Trust me." (−$6)','Mugsy');}}
   else if(o==='water')c.say('"Tap water," Mugsy repeats, flatly, and serves it in a glass that says WORLD’S OKAYEST CUSTOMER.','Mugsy');
   else if(o==='tips')c.say('"Velvet Rope’s got a rooftop show at two. Brick on the door wants a password and good hair. The DJ headlining is that sheepdog sleeping it off in Rufus’s suite. And the comic at the diner? Smartest dog in town. Don’t use a pickup line on her. Use your ears."','Mugsy');
   else c.say('Mugsy nods and goes back to polishing the same glass he has polished since 1998.','Mugsy');}},
 pixel:{ask:c=>({who:'Pixel',prompt:'"Yeah?" Pixel doesn’t look up from her phone.',options:[{id:'mints',label:'Breath mints, please. ($2)'},{id:'hotdog',label:'One of those hot dogs. ($1)'},{id:'roses',label:'The roses. ($3)'},{id:'book',label:'"1001 Pickup Lines". ($4)'},{id:'ticket',label:'A scratch-off. ($1)'},{id:'chat',label:'What are you playing?'}]}),
  answer:(c,o)=>{if(o==='mints')buy(c,'mints',2,'Pixel scans the mints like they’re evidence.');else if(o==='hotdog')buy(c,'hotdog',1,'Pixel hands it over with tongs and genuine concern. "Don’t eat that. Like, as a friend."');else if(o==='roses')buy(c,'roses',3,'One petal falls off in protest.');else if(o==='book')buy(c,'book',4,'Pixel snorts. "Bold strategy."');else if(o==='ticket'){if(c.has('ticket')){c.say('"Scratch the one you got first, high roller."','Pixel');return;}buy(c,'ticket',1,'"Good luck," Pixel says, in a tone that means bad luck.');}
   else c.say('"DAWG Dash," Pixel says. "I’m on the leaderboard. Global. You?" You are not. "Figures."','Pixel');}},
 bean:{ask:c=>({who:'Bean',prompt:'"Coffee, hon? Pie? Life advice? Only one of those is free."',options:[{id:'espresso',label:'A double espresso to go. ($5)'},{id:'pie',label:'What’s the mystery pie?'},{id:'nova',label:'Who’s the comic in the booth?'},{id:'advice',label:'Life advice, please.'}]}),
  answer:(c,o)=>{if(o==='espresso'){if(c.has('espresso')){c.say('"You’ve got one. Drink that, or give it to someone who needs it more."','Bean');return;}if(c.pay(5)){c.give('espresso',true);c.say('Bean pulls a double espresso so strong the cup sweats. "Careful. That’ll wake the dead." (−$5)','Bean');c.award('espresso');}}
   else if(o==='pie')c.say('"Nobody’s ever ordered it," Bean says. "And nobody ever will. Next question."','Bean');
   else if(o==='nova')c.say('"Nova. Funniest girl in the city, headlining the rooftop at two if her nerves don’t eat her. Lost her joke notebook tonight. Be nice, or I’ll know."','Bean');
   else c.say('"Listen more than you talk. Tip more than you think. And never, ever eat the Kwik-Sit hot dogs."','Bean');}},
 nova:{ask:c=>({who:'Nova',prompt:c.flag('novaMet')?'Nova sighs. "You again."':'Nova looks up from the napkin. "Can I help you?"',options:[{id:'often',label:'"Do you come here often?"'},{id:'wifi',label:'"Is your name Wi-Fi? Because I feel a connection."'},{id:'honest',label:'"You look stressed. Rough night?"'},{id:'bye',label:'"Never mind. Enjoy your napkin."'}]}),
  answer:(c,o)=>{c.flag('novaMet',true);if(o==='often')c.say('"I come here every night to write jokes," Nova says. "Tonight I have a new one: a dog in a velvet suit walks into a diner. That’s it. That’s the joke."','Nova');
   else if(o==='wifi')c.say('"Is your name dial-up?" Nova asks. "Because you’re making a terrible noise and I want you to stop." The diner applauds. You bow, because what else is there.','Nova');
   else if(o==='honest'){c.say('Nova blinks. She wasn’t expecting a real question. "I lost my joke notebook. My whole closing set. I’m on the roof at two and I’ve got nothing but this napkin." She frowns. "I think I left it at Lucky Paws. I was ‘researching material’ at the blackjack table. Meaning losing."','Nova');c.flag('novaAsked',true);c.award('honest');}
   else c.say('"It’s a good napkin," Nova calls after you. "Better company than most."','Nova');}},
 novaNotebook:{ask:c=>({who:'Nova',prompt:'Nova spots the notebook in your paw. Her ears go straight up.',options:[{id:'give',label:'"I think this is yours."'},{id:'read',label:'Read her a joke from it first.'}]}),
  answer:(c,o)=>{if(o==='read'){c.say('You read aloud: "Dating apps are just fetch with extra steps." Nova snatches the notebook. "You don’t read a comic’s notebook. You don’t read a comic’s notebook!" But she’s smiling.','Nova');}LOCATIONS.diner.hotspots.nova.give.notebook(c);}},
 dealer:{ask:c=>({who:'Dice',prompt:'"Blackjack, ten dollars a hand. Or are you here for the free mints?"',options:[{id:'play',label:'Deal me in. ($10)'},{id:'notebook',label:'That notebook by your chips…',when:c=>!c.flag('notebookGiven')},{id:'tips',label:'Any tips?'}]}),
  answer:(c,o)=>{if(o==='play'){if(!c.pay(10))return;c.time(6);const you=15+Math.floor(c.rnd()*7),him=16+Math.floor(c.rnd()*6),bust=you>21;c.flag('handYou',you);c.flag('handHim',him);c.say(`Dice deals. You have ${you}. He shows a face card.`,'Dice');c.choose('hitStand');}
   else if(o==='notebook'){if(c.flag('novaAsked')){c.flag('notebookGiven',true);c.give('notebook',true);c.say('"Lost property goes to whoever can describe it," Dice says. You describe Nova: denim jacket, terrier, eyebrows that judge. Dice nods. "She lost forty dollars and her dignity at this table. Tell her the dignity’s non-refundable." He hands you the notebook.','Dice');c.say('You got: Joke notebook.','*');}else c.say('"Finders aren’t keepers at Lucky Paws," Dice says. "Whoever lost it can describe it. Do you even know whose it is?"','Dice');}
   else c.say('"Never hit on sixteen when I’m showing a face card. And never play when you need the money." He looks at your suit. "Which means you shouldn’t play."','Dice');}},
 hitStand:{ask:c=>({who:'Dice',prompt:`You have ${c.flag('handYou')}. Hit or stand?`,options:[{id:'hit',label:'Hit me.'},{id:'stand',label:'Stand.'}]}),
  answer:(c,o)=>{let you=c.flag('handYou');const him=c.flag('handHim');if(o==='hit'){const card=2+Math.floor(c.rnd()*9);you+=card;c.say(`You draw a ${card}. That’s ${you}.`,'Dice');}
   if(you>21){c.say('Bust. Dice rakes in your chips without emotion. Greyhounds do not gloat. They don’t have to.','Dice');return;}if(you>him||him>21){c.earn(20);c.say(`Dice has ${him}. You win! He pushes $20 across the felt. "Beginner’s luck," he says. "It runs out."`,'Dice');}else if(you===him){c.earn(10);c.say(`Dice has ${him}. Push. You get your $10 back.`,'Dice');}else c.say(`Dice has ${him}. The house wins. The house always wags.`,'Dice');}},
 brick:{ask:c=>({who:'Brick',prompt:'Brick looks down at you. A long way down. "Password."',options:[{id:'moon',label:'"MOON."',when:c=>c.has('flyer')},{id:'bass',label:'"…BASS?"'},{id:'please',label:'"Please?"'},{id:'collar',label:'"Nice collar. Did your mom pick it?"'}]}),
  answer:(c,o)=>{if(o==='collar'){c.die('brick');return;}if(o!=='moon'){const n=(c.flag('wrong')||0)+1;c.flag('wrong',n);c.say(n>=3?'"Three strikes," Brick says, and lifts you over the rope by the scruff, onto the curb. Pedestrians step around you. You lie there and think about your choices.':'"Nope," Brick says. The clipboard does not move. Somewhere, a flyer is laughing at you.','Brick');if(n>=3){c.flag('wrong',0);c.time(20);}return;}
   if(!c.flag('styled')){c.say('"Password’s right," Brick says. "Hair’s wrong. Looks like it lost a fight with a ceiling fan. Fix it."','Brick');return;}if(!c.flag('fresh')){c.say('"Password’s right. Hair’s acceptable." He leans in, sniffs, and recoils. "Breath could strip paint. Mints. Then come back."','Brick');return;}
   c.give('wristband',true);c.say('Brick checks his clipboard, checks your hair, checks your breath. Then, almost imperceptibly, he nods. He snaps a VIP wristband on your paw. "Lift’s at the back. Welcome to the Velvet Rope."','Brick');c.say('You got: VIP wristband.','*');c.award('wristband');}},
 elevator:{ask:c=>({who:null,prompt:'The elevator panel: PENTHOUSE (key card needed) and a big red EMERGENCY button.',options:[{id:'pent',label:'Press PENTHOUSE.'},{id:'red',label:'Press the big red button.'},{id:'none',label:'Leave it.'}]}),
  answer:(c,o)=>{if(o==='red'){c.die('elevator');return;}if(o==='pent'){if(c.has('key'))c.travel('penthouse');else c.say('The penthouse button blinks: KEY CARD REQUIRED. Duchess watches you try. Duchess is enjoying this.');return;}c.say('You step back from the panel. The red button looks disappointed in you.');}},
 rover:{ask:c=>({who:'Reverend Rover',prompt:'"Welcome to Bark & Wed! Hitched in four minutes or your money back. Got a partner, sugar?"',options:[{id:'how',label:'How does this work?'},{id:'partner',label:'Can you find me a partner?'},{id:'rose',label:'Can I get a rose?'}]}),
  answer:(c,o)=>{if(o==='how')c.say('"Twenty dollars for the license at the desk. Bring a partner who says yes. I do the rest, with feeling." He winks so hard his rhinestones rattle.','Reverend Rover');else if(o==='partner')c.say(c.flag('proposal')?'"Lady Luck from the casino? She’s proposed to half the city. She’s waiting by the slots. Get a license and say the word."':'"I marry them, sugar. I don’t find them. The cardboard cutout of me doesn’t count either. It’s been tried."','Reverend Rover');else c.say('"One dollar donation, take a rose from the table. The Lord sees. So does Rover."','Reverend Rover');}},
 wedding:{ask:c=>({who:'Reverend Rover',prompt:'"A license! Who’s the lucky partner?"',options:[{id:'luck',label:'"Lady Luck. Call her."',when:c=>c.flag('proposal')},{id:'self',label:'"Can I marry myself?"'},{id:'wait',label:'"Actually, let me think about it."'}]}),
  answer:(c,o)=>{if(o==='luck'){c.drop('license');c.say('Reverend Rover makes a call. Ten minutes later, Lady Luck bursts through the door in a cloud of glitter. "I KNEW YOU’D COME," she booms. "I DO," you hear yourself say.','Reverend Rover');c.end('luck');}else if(o==='self')c.say('"Sugar, you’re gonna have to love yourself first. That one takes longer than four minutes."','Reverend Rover');else c.say('"Take your time. You’ve got until sunrise. Then the license turns into a pumpkin."','Reverend Rover');}},
 velma:{ask:c=>({who:'Velma',prompt:c.has('opener')?'Velma checks your laminate. "Vinyl’s opener? You’re on whenever you’re ready, babe."':'"Who are you? You’re not on my list. Nobody’s on my list. My headliner is missing."',options:[{id:'perform',label:'Hit the stage. With the Midnight demo.',when:c=>c.has('opener')&&c.has('demo')},{id:'wing',label:'Grab the mic and wing it.'},{id:'nova',label:'Is Nova on tonight?'},{id:'later',label:'Not yet.'}]}),
  answer:(c,o)=>{if(o==='perform'){c.say('You walk out. The lights hit. You drop DJ Vinyl’s Midnight demo and the whole roof jumps at once.','Velma');c.end(c.flag('romance')?'legend':'headliner');}else if(o==='wing'){c.say('You grab the mic before Velma can stop you. You have no set. You have no track. You have a velvet suit and confidence you have not earned.','Velma');c.end('flop');}else if(o==='nova')c.say(c.flag('novaDate')?'"Nova’s closing. If she shows. She lost her notebook earlier, poor thing."':'"Nova? Closing tonight, if she finds her notebook. Without it she says she’s ‘just a terrier with feelings.’"','Velma');else c.say('"Clock’s ticking, babe. Show starts at two, sun comes up at six."','Velma');}},
 novaRoof:{ask:c=>({who:'Nova',prompt:c.flag('romance')?'Nova smiles at you over the rose. "So. What now?"':'"You came," Nova says. "And you’re only a little weird."',options:[{id:'show',label:'"Want to steal the show together?"',when:c=>c.has('opener')&&c.has('demo')},{id:'breakfast',label:'"Forget the show. Breakfast?"',when:c=>c.flag('romance')},{id:'nerves',label:'"Nervous?"'},{id:'line',label:'Try a pickup line.'}]}),
  answer:(c,o)=>{if(o==='show'){c.say('"Together?" Nova grins. "You open, I close. If you flop, I’ll make fun of you in my set. Deal?" Deal.','Nova');if(!c.flag('romance'))c.say('She squeezes your paw, then lets go. "Something tells me you could’ve brought flowers, though."','Nova');}else if(o==='breakfast'){c.say('"Pancakes," Nova says. "Followed by more pancakes." You sit on the roof edge together and watch the crowd, then the sky.','Nova');c.end('breakfast');}else if(o==='nerves')c.say('"Terrified. Comedy is just being scared in front of strangers on purpose." She taps her notebook. "This helps. You helped."','Nova');else c.say('"Don’t," Nova says, smiling. "We’ve moved past that. Bring me something real."','Nova');}}
};

const TRAVEL_TEXT=['The cab smells like a wet dog. You are a dog. You smell like a wet dog too. It works out.','Your cabbie, a husky, tells you about his screenplay. It’s about a husky who drives a cab.','The cab hits every red light. The driver takes it personally.'];
export const CONTENT={
 start:'bar',startItems:['comb'],startMoney:40,sunrise:480,sunriseEnding:'alone',costs:{act:3,talk:5},maxScore:MAX_SCORE,
 items:ITEMS,locations:LOCATIONS,dialogs:DIALOGS,deaths:DEATHS,endings:ENDINGS,awards:AWARDS,
 flags:['flyerTaken','quarterTaken','called','styled','fresh','pool','keyGiven','rufusTold','catsFed','ladderDown','umbrellaTaken','novaMet','novaAsked','novaDate','novaGone','romance','notebookGiven','djAwake','robeTaken','shadesTaken','roseTaken','proposal','chip','rocket','wrong','handYou','handHim','wished'],
 intro:'AFTER HOURS. One velvet suit. One night. Too many bad decisions. Get on stage at the rooftop show, win over Nova, or both, before the sun comes up at 6:00 AM.',
 sunriseText:'The sky goes pink. Then orange. Then, worst of all, bright.',
 places:TAXI_STOPS,
 placeFor:(c,name)=>{const n=String(name||'').toLowerCase();const map={bar:['bar','rusty','collar','dive'],store:['store','kwik','shop','convenience'],diner:['diner','last bite','cafe','coffee'],casino:['casino','lucky','paws','slots'],club:['club','velvet','rope','disco'],hotel:['hotel','kennel','lobby'],chapel:['chapel','wed','wedding','church'],alley:['alley','back'],rooftop:['roof','rooftop','show','stage'],penthouse:['penthouse','suite','1201']};return Object.keys(map).find(k=>map[k].some(w=>n.includes(w)))||null;},
 route:(c,dest)=>{const from=c.state.loc;
  if(dest==='alley')return from==='bar'||from==='rooftop'&&c.flag('ladderDown')?{ok:true,minutes:2,text:from==='bar'?'You push through the back door into the alley.':'You climb down the fire escape.'}:{ok:false,why:'The alley is behind The Rusty Collar. Go through the bar’s back door.'};
  if(dest==='bar'&&from==='alley')return {ok:true,minutes:2,text:'Back inside the Rusty Collar. Mugsy doesn’t look up.'};
  if(dest==='rooftop'){if(from==='club'&&c.has('wristband'))return {ok:true,minutes:3,text:'The VIP lift hums upward. Your ears pop. Your hopes rise.'};if(from==='alley'&&c.flag('ladderDown')&&c.flag('catsFed'))return {ok:true,minutes:5,text:'You climb the fire escape, four floors of clanging metal and bad knees.'};return {ok:false,why:from==='club'?'The VIP lift needs a VIP wristband.':'The rooftop is above The Velvet Rope: up the club’s VIP lift, or the fire escape in the alley.'};}
  if(dest==='penthouse'){if(from==='hotel'&&c.has('key'))return {ok:true,minutes:3,text:'The elevator glides up to the twelfth floor with a soft "ding" that sounds expensive.'};return {ok:false,why:from==='hotel'?'The penthouse elevator needs a key card.':'The penthouse is at The Kennel Club Hotel, up the elevator.'};}
  if(dest==='hotel'&&from==='penthouse')return {ok:true,minutes:3,text:'Down to the lobby. Duchess watches you exit the elevator like you stole it.'};
  if(dest==='club'&&from==='rooftop')return {ok:true,minutes:3,text:'The lift drops you back into the bass.'};
  if(from==='rooftop'||from==='penthouse')return {ok:false,why:'Taxis don’t pick up from up here. Head back down first.'};
  if(from==='alley')return {ok:false,why:'Head back through the bar first. The cats don’t do valet.'};
  if(!TAXI_STOPS[dest])return {ok:false,why:'Nobody knows that place, including you.'};
  if(c.state.money>=FARE)return {ok:true,fare:FARE,minutes:RIDE,text:`You hail a cab to ${TAXI_STOPS[dest]}. (−$${FARE}) `+TRAVEL_TEXT[Math.floor(c.rnd()*TRAVEL_TEXT.length)]};
  return {ok:true,minutes:WALK,text:`No cab fare, so you walk to ${TAXI_STOPS[dest]}. Your paws file a complaint.`};},
 taxiText:c=>'Taxi stops ($5, or walk for free and slow): '+Object.values(TAXI_STOPS).join(', ')+'. Type "go casino", "go diner", and so on.',
 hint:c=>{const f=k=>c.flag(k),h=k=>c.has(k);
  if(!f('flyerTaken'))return 'The jukebox at the Rusty Collar has something stuck in it.';
  if(!f('styled'))return 'Brick likes good hair. There’s a mirror in the bar restroom, and you have a comb.';
  if(!f('fresh'))return 'Brick also has a nose. Kwik-Sit sells breath mints.';
  if(!h('wristband')&&!h('opener'))return 'With the password, good hair and fresh breath, talk to Brick at the Velvet Rope.';
  if(!f('novaAsked'))return 'The comic at The Last Bite is having a rough night. Try asking how she’s doing, honestly.';
  if(!f('notebookGiven'))return 'Nova left her notebook at the blackjack table in Lucky Paws. Ask Dice about it.';
  if(h('notebook'))return 'Nova is waiting at The Last Bite. Give her the notebook.';
  if(!f('keyGiven'))return 'Old Rufus at the Rusty Collar will trade his penthouse key for a Whiskey Biscuit.';
  if(!h('espresso')&&!f('djAwake'))return 'DJ Vinyl needs waking. Bean at The Last Bite makes a double espresso.';
  if(!f('djAwake'))return 'Take the espresso up to suite 1201 at The Kennel Club Hotel and use it on DJ Vinyl.';
  if(!f('roseTaken'))return 'Nova deserves a real flower, not the Kwik-Sit ones. Try the chapel.';
  if(c.state.minute<240)return 'The rooftop show starts at 2:00 AM. Nova arrives then.';
  if(!f('romance'))return 'Find Nova on the rooftop and give her the rose.';
  return 'Talk to Velma on the rooftop and hit the stage with the Midnight demo.';},
 unknown:(c,raw)=>['I don’t know how to "'+raw+'". Try look, talk, take, use, give or go.','"'+raw+'"? The narrator stares at you. You stare back. Nobody wins.','You try to '+raw+'. The universe declines.'][Math.floor(c.rnd()*3)],
 notHere:(c,n)=>`There’s no "${n}" here. You look under a chair just in case.`,
 what:(c,verb)=>({look:'Look at what?',talk:'Talk to whom? The voices in your head are busy.',take:'Take what?',use:'Use what? On what?',give:'Give what, to whom?',buy:'Buy what?',drink:'Drink what?',eat:'Eat what?',wear:'Wear what?',open:'Open what?',push:'Push what?'})[verb]||'What?',
 cantDo:(c,verb,name)=>({take:`You can’t take the ${name}. It’s bolted down, legally or emotionally.`,talk:`You talk to the ${name}. It does not talk back. Classic ${name}.`,eat:`You consider eating the ${name}. You reconsider.`,drink:`You can’t drink the ${name}.`,wear:`The ${name} doesn’t go with velvet.`,open:`The ${name} doesn’t open.`,push:`You push the ${name}. Nothing happens, except mild embarrassment.`,buy:`The ${name} isn’t for sale.`,use:`You use the ${name}. Somehow.`,look:`It’s a ${name}.`})[verb]||`You can’t ${verb} the ${name}.`,
 noUse:(c,item,target)=>`Using the ${item} on the ${target} doesn’t do anything. You put it away and act like you meant to.`,
 noPlace:(c,n)=>`There’s no "${n}" in this city. Try a taxi stop: ${Object.values(TAXI_STOPS).join(', ')}.`,
 dog:(c,w)=>({bark:'You bark. Everyone looks. You pretend it was a cough.',howl:'You howl. Somewhere across the city, another dog howls back. Solidarity.',woof:'Woof. Concise. Powerful.',sit:'You sit. Nobody gives you a treat. Tough crowd.',beg:'You beg. It is not dignified, and it does not work.','roll over':'You roll over in your velvet suit. It picks up a lot of floor.','play dead':'You play dead. The narrator checks your pulse. Still alive. Disappointing.',wag:'You wag. Your whole back half wags. You can’t help it.',sniff:'You sniff the air: perfume, fries and somebody’s bad decision.',fetch:'You fetch an imaginary ball. You are very proud.',lick:'You lick the air. Better than licking anything else in here.',dance:'You do a little dance. It’s fine. Nobody saw. Everybody saw.',scratch:'You scratch behind your ear with your back paw. Very suave.',growl:'You growl. A chihuahua somewhere laughs at you.',whine:'You whine. The narrator rolls their eyes.',stay:'You stay. Good dog.',shake:'You shake. Water you didn’t know you had flies everywhere.','high five':'You high-five the air. The air leaves you hanging.','chase tail':'You chase your tail for a full minute. You do not catch it. You never do.',dig:'You try to dig through the floor. It’s concrete. And a crime.'})[w]||'You '+w+'.',
 arrive:(c,dest)=>{}
};
